needle="""${!published?`<section id=\"preflight\" class=\"notice\"></section>"""
insert="""${!published?`<section class=\"review-metadata-grid\"><article class=\"card metadata-card\"><div class=\"section-head\"><div><p class=\"eyebrow\">Search visibility</p><h2>SEO Review</h2><p class=\"helper\">Review these Yoast-compatible values. They are saved locally and do not change the article unless you edit the article fields.</p></div><span class=\"tag\">editable</span></div><label for=\"reviewFocusKeyphrase\">Focus keyphrase<input id=\"reviewFocusKeyphrase\" type=\"text\" maxlength=\"80\" placeholder=\"e.g. apple pie oatmeal cookies\"></label><label for=\"reviewSeoTitle\">SEO title<input id=\"reviewSeoTitle\" type=\"text\" maxlength=\"160\"></label><label for=\"reviewSeoDescription\">Meta description<textarea id=\"reviewSeoDescription\" rows=\"3\" maxlength=\"160\"></textarea></label><div class=\"metadata-counts\"><span id=\"seoTitleCount\"></span><span id=\"seoDescriptionCount\"></span></div></article><article class=\"card metadata-card\"><div class=\"section-head\"><div><p class=\"eyebrow\">Pinterest publishing</p><h2>Pinterest Review</h2><p class=\"helper\">AI-generated fields stay separate. Review them before using Direct API or manual Pinterest publishing.</p></div><span class=\"tag\">editable</span></div><label for=\"reviewPinterestTitle\">Pinterest title<input id=\"reviewPinterestTitle\" type=\"text\" maxlength=\"100\"></label><label for=\"reviewPinterestDescription\">Pinterest description<textarea id=\"reviewPinterestDescription\" rows=\"4\" maxlength=\"800\"></textarea></label><label for=\"reviewPinterestAlt\">Image alt text<input id=\"reviewPinterestAlt\" type=\"text\" maxlength=\"320\"></label><div class=\"metadata-preview\"><strong>Preview</strong><h3 id=\"pinterestPreviewTitle\"></h3><p id=\"pinterestPreviewDescription\"></p><small id=\"pinterestPreviewAlt\"></small></div></article></section><section id=\"preflight\" class=\"notice\"></section>"`"""
