old="""draft.title=title;draft.metaDescription=$('editMeta')?.value.trim()||'';draft.slug="""
new="""draft.title=title;draft.metaDescription=$('editMeta')?.value.trim()||'';draft.seo={focusKeyphrase:$('reviewFocusKeyphrase')?.value.trim()||'',title:$('reviewSeoTitle')?.value.trim()||draft.title,metaDescription:$('reviewSeoDescription')?.value.trim()||draft.metaDescription};draft.pinterest={...(draft.pinterest||{}),title:$('reviewPinterestTitle')?.value.trim()||draft.pinterestTitle||draft.title,description:$('reviewPinterestDescription')?.value.trim()||draft.pinterestDescription||draft.metaDescription,altText:$('reviewPinterestAlt')?.value.trim()||draft.pinterestAltText||draft.title};draft.pinterestTitle=draft.pinterest.title;draft.pinterestDescription=draft.pinterest.description;draft.pinterestAltText=draft.pinterest.altText;draft.slug="""
if old not in s: raise SystemExit('save marker missing')
s=s.replace(old,new,1)
old2="""editTitle.value=draft.title||'';editMeta.value=draft.metaDescription||'';editSlug.value=draft.slug||'';editHtml.value=draft.htmlContent||'';editRecipes.value="""
new2="""editTitle.value=draft.title||'';editMeta.value=draft.metaDescription||'';editSlug.value=draft.slug||'';editHtml.value=draft.htmlContent||'';editRecipes.value="""
