# Initialize metadata controls and live preview immediately after the existing edit field setup.
needle3="""renderRecipeImageManager(draft,recipes)}const saveVersion="""
insert3="""renderRecipeImageManager(draft,recipes);$('reviewFocusKeyphrase').value=seo.focusKeyphrase||'';$('reviewSeoTitle').value=seo.title||draft.title||'';$('reviewSeoDescription').value=seo.metaDescription||draft.metaDescription||'';$('reviewPinterestTitle').value=pinterest.title||draft.pinterestTitle||draft.title||'';$('reviewPinterestDescription').value=pinterest.description||draft.pinterestDescription||draft.metaDescription||'';$('reviewPinterestAlt').value=pinterest.altText||draft.pinterestAltText||draft.title||'';const refreshMetadataPreview=()=>{$('seoTitleCount').textContent=`${$('reviewSeoTitle').value.length}/160`;$('seoDescriptionCount').textContent=`${$('reviewSeoDescription').value.length}/160`;$('pinterestPreviewTitle').textContent=$('reviewPinterestTitle').value;$('pinterestPreviewDescription').textContent=$('reviewPinterestDescription').value;$('pinterestPreviewAlt').textContent=`Alt: ${$('reviewPinterestAlt').value}`};['reviewSeoTitle','reviewSeoDescription','reviewPinterestTitle','reviewPinterestDescription','reviewPinterestAlt'].forEach(id=>$(id).addEventListener('input',refreshMetadataPreview));refreshMetadataPreview()}const saveVersion="""
